input.command:
cat > /tmp/fceval-i3-t1-zjdlyodo/zones.js <<'EOF'
for (const d of ["10001","60601","33101","98101","96813"]) {
  await page.goto("https://postcalc.usps.com/DomesticZoneChart/");
  await page.fill("#Origin","94107");
  await page.fill("#Destination", d);
  await page.locator("form:has(#Destination) input[type=submit]").click();
  await page.waitForLoadState("networkidle");
  const t = await page.innerText("main, body");
  const i = t.indexOf("Zone");
  console.log("DEST "+d+" => "+t.replace(/\s+/g," ").slice(Math.max(0,t.search(/Your Zone|Zone for|Zone:/i)),  Math.max(0,t.search(/Your Zone|Zone for|Zone:/i))+300));
}
EOF
timeout 200 firecrawl interact -s 01a15529-df36-70bd-a660-65c8314c94b7 --timeout 180 -c "$(cat /tmp/fceval-i3-t1-zjdlyodo/zones.js)" 2>&1 | tail -15

